import random
import re


class TreasureGridEnv:
    GRID_SIZE = 8
    MAX_STEPS = 10

    def __init__(self):
        self.rng = None
        self.treasure_row = None
        self.treasure_col = None
        self.row_candidates = None
        self.col_candidates = None
        self.row_solved_rewarded = False
        self.col_solved_rewarded = False
        self.steps_taken = 0
        self.done = False

    def reset(self, seed=None):
        self.rng = random.Random(seed)
        self.treasure_row = self.rng.randint(1, self.GRID_SIZE)
        self.treasure_col = self.rng.randint(1, self.GRID_SIZE)
        self.row_candidates = set(range(1, self.GRID_SIZE + 1))
        self.col_candidates = set(range(1, self.GRID_SIZE + 1))
        self.row_solved_rewarded = False
        self.col_solved_rewarded = False
        self.steps_taken = 0
        self.done = False

        obs = (
            "A pirate's map divides the island into an 8x8 grid: rows 1 (northmost) "
            "to 8 (southmost), columns 1 (westmost) to 8 (eastmost). The treasure sits "
            "at one hidden (row, col) cell. You have 10 total actions to find it.\n"
            "Actions (send exactly one per turn):\n"
            "  PROBE ROW <n>     -- learn whether the treasure is north/south of row n, or an exact match\n"
            "  PROBE COL <n>     -- learn whether the treasure is west/east of column n, or an exact match\n"
            "  GUESS <row> <col> -- claim the exact cell; a correct claim ends the game\n"
            "n must be an integer from 1 to 8. You win by sending a correct GUESS."
        )
        info = {"row_candidates": len(self.row_candidates), "col_candidates": len(self.col_candidates)}
        return obs, info

    def _corrective(self, msg):
        self.steps_taken += 1
        truncated = self.steps_taken >= self.MAX_STEPS and not self.done
        return msg, 0.0, False, truncated, {"steps_remaining": self.MAX_STEPS - self.steps_taken}

    def step(self, action):
        if self.done:
            return "The episode has already ended.", 0.0, True, False, {}

        text = (action or "").strip().upper()
        m_probe = re.fullmatch(r"PROBE\s+(ROW|COL)\s+(-?\d+)", text)
        m_guess = re.fullmatch(r"GUESS\s+(-?\d+)\s+(-?\d+)", text)

        if m_probe:
            axis, n_str = m_probe.groups()
            n = int(n_str)
            if not (1 <= n <= self.GRID_SIZE):
                return self._corrective(
                    f"Malformed probe: {n} is outside 1-{self.GRID_SIZE}. "
                    "Use PROBE ROW <n> or PROBE COL <n> with n in 1-8."
                )
            self.steps_taken += 1
            reward = 0.0

            if axis == "ROW":
                target = self.treasure_row
                if n == target:
                    self.row_candidates &= {n}
                    obs = f"Exact match! The treasure's row is {n}."
                elif n < target:
                    self.row_candidates = {r for r in self.row_candidates if r > n}
                    obs = f"The treasure is south of row {n}."
                else:
                    self.row_candidates = {r for r in self.row_candidates if r < n}
                    obs = f"The treasure is north of row {n}."
                if len(self.row_candidates) == 1 and not self.row_solved_rewarded:
                    reward += 0.25
                    self.row_solved_rewarded = True
                    obs += " (Row narrowed to a single possibility.)"
                obs += (
                    f" [{len(self.row_candidates)} row candidate(s), "
                    f"{len(self.col_candidates)} col candidate(s) remain]"
                )
            else:
                target = self.treasure_col
                if n == target:
                    self.col_candidates &= {n}
                    obs = f"Exact match! The treasure's column is {n}."
                elif n < target:
                    self.col_candidates = {c for c in self.col_candidates if c > n}
                    obs = f"The treasure is east of column {n}."
                else:
                    self.col_candidates = {c for c in self.col_candidates if c < n}
                    obs = f"The treasure is west of column {n}."
                if len(self.col_candidates) == 1 and not self.col_solved_rewarded:
                    reward += 0.25
                    self.col_solved_rewarded = True
                    obs += " (Column narrowed to a single possibility.)"
                obs += (
                    f" [{len(self.row_candidates)} row candidate(s), "
                    f"{len(self.col_candidates)} col candidate(s) remain]"
                )

            truncated = self.steps_taken >= self.MAX_STEPS
            info = {"row_candidates": len(self.row_candidates), "col_candidates": len(self.col_candidates)}
            return obs, reward, False, truncated, info

        if m_guess:
            r_str, c_str = m_guess.groups()
            r, c = int(r_str), int(c_str)
            if not (1 <= r <= self.GRID_SIZE and 1 <= c <= self.GRID_SIZE):
                return self._corrective(
                    f"Malformed guess: coordinates must be integers in 1-{self.GRID_SIZE}."
                )
            self.steps_taken += 1
            if r == self.treasure_row and c == self.treasure_col:
                self.done = True
                return (
                    f"Correct! The treasure was at ({r}, {c}). You found it.",
                    0.5,
                    True,
                    False,
                    {"row_candidates": 1, "col_candidates": 1},
                )
            hint_parts = [
                "row correct" if r == self.treasure_row else "row wrong",
                "col correct" if c == self.treasure_col else "col wrong",
            ]
            truncated = self.steps_taken >= self.MAX_STEPS
            obs = f"Wrong guess ({r}, {c}): {', '.join(hint_parts)}. Keep probing or guess again."
            info = {"row_candidates": len(self.row_candidates), "col_candidates": len(self.col_candidates)}
            return obs, 0.0, False, truncated, info

        return self._corrective(
            "Unrecognized action. Use 'PROBE ROW <n>', 'PROBE COL <n>', or 'GUESS <row> <col>' with n in 1-8."
        )

import random
import re
import string


class RLEHiddenRuleEnv:
    """Infer a hidden run-length expansion rule from probes, then predict a target expansion."""

    LETTERS = string.ascii_lowercase[:10]
    STEP_LIMIT = 10
    _ACTION_RE = re.compile(r"^PREDICT\s+(\S+)\s+(\S+)$")

    def __init__(self):
        self.rng = None
        self.order = None
        self.shift = None
        self.target_token = None
        self.target_expansion = None
        self.revealed = {}
        self.novel_hits = 0
        self.steps = 0
        self.done = False

    def _make_run(self):
        count = self.rng.randint(1, 4)
        letter = self.rng.choice(self.LETTERS)
        return count, letter

    def _make_token(self, runs):
        parts = []
        for count, letter in runs:
            if self.order == "digit_first":
                parts.append(f"{count}{letter}")
            else:
                parts.append(f"{letter}{count}")
        return "".join(parts)

    def _expand(self, runs):
        out = []
        for count, letter in runs:
            shifted = chr((ord(letter) - ord('a') + self.shift) % 26 + ord('a'))
            out.append(shifted * count)
        return "".join(out)

    def _random_runs(self):
        n = self.rng.randint(2, 3)
        return [self._make_run() for _ in range(n)]

    def _fresh_token(self, existing):
        for _ in range(50):
            runs = self._random_runs()
            token = self._make_token(runs)
            if token not in existing:
                return token, runs
        runs = self._random_runs()
        return self._make_token(runs), runs

    def _expand_token_string(self, token):
        if self.order == "digit_first":
            pattern = re.compile(r"(\d)([a-j])")
        else:
            pattern = re.compile(r"([a-j])(\d)")
        pos = 0
        runs = []
        while pos < len(token):
            m = pattern.match(token, pos)
            if not m:
                return None
            if self.order == "digit_first":
                count, letter = int(m.group(1)), m.group(2)
            else:
                letter, count = m.group(1), int(m.group(2))
            if count < 1:
                return None
            runs.append((count, letter))
            pos = m.end()
        if not runs:
            return None
        return self._expand(runs)

    def reset(self, seed=None):
        self.rng = random.Random(seed)
        self.order = self.rng.choice(["digit_first", "letter_first"])
        self.shift = self.rng.randint(0, 4)
        self.steps = 0
        self.done = False
        self.novel_hits = 0
        self.revealed = {}

        examples = []
        for _ in range(2):
            token, runs = self._fresh_token(self.revealed)
            expansion = self._expand(runs)
            self.revealed[token] = expansion
            examples.append((token, expansion))

        target_token, target_runs = self._fresh_token(self.revealed)
        self.target_token = target_token
        self.target_expansion = self._expand(target_runs)
        self.revealed[target_token] = self.target_expansion

        ex_lines = "\n".join(f"  {t} -> {e}" for t, e in examples)
        obs = (
            "Tokens are compressed runs of COUNT+LETTER or LETTER+COUNT (one fixed order "
            "used throughout this episode). Each run means 'repeat a letter COUNT times', "
            "but the letter is first shifted by a fixed hidden amount (a Caesar shift) "
            "before repeating.\n"
            f"Examples of the hidden rule applied:\n{ex_lines}\n"
            f"Your target token to expand is: {self.target_token}\n"
            "Actions (one per step): PREDICT <token> <expansion>\n"
            "  If <token> is new (not shown above and not already predicted), a correct "
            "prediction proves your hypothesis and scores partial credit; a wrong one "
            "reveals the true expansion so you can refine your hypothesis.\n"
            f"  Predicting {self.target_token} correctly wins the episode; wrong guesses "
            "on it are told only right/wrong, with no reveal.\n"
            f"You have {self.STEP_LIMIT} steps total, letters used are 'a'-'j' only."
        )
        return obs, {}

    def step(self, action):
        if self.done:
            return "Episode already finished.", 0.0, True, False, {}

        self.steps += 1
        match = self._ACTION_RE.match(action.strip())

        if not match:
            obs = "Malformed action. Use: PREDICT <token> <expansion>"
            truncated = self.steps >= self.STEP_LIMIT
            self.done = truncated
            return obs, 0.0, False, truncated, {}

        token, guess = match.group(1), match.group(2)

        if token == self.target_token:
            if guess == self.target_expansion:
                obs = f"Correct! {token} -> {guess}. Target solved."
                self.done = True
                return obs, 0.4, True, False, {}
            obs = "Incorrect for the target token. No reveal. Keep probing other tokens."
            truncated = self.steps >= self.STEP_LIMIT
            self.done = truncated
            return obs, 0.0, False, truncated, {}

        already_seen = token in self.revealed
        actual = self.revealed.get(token)
        if actual is None:
            actual = self._expand_token_string(token)
            if actual is None:
                obs = (
                    f"'{token}' is not a valid token under the fixed order (all tokens use "
                    "the same COUNT/LETTER order and letters 'a'-'j'). Try a differently formed token."
                )
                truncated = self.steps >= self.STEP_LIMIT
                self.done = truncated
                return obs, 0.0, False, truncated, {}
            self.revealed[token] = actual

        correct = guess == actual
        if correct and not already_seen and self.novel_hits < 2:
            self.novel_hits += 1
            obs = f"Correct! {token} -> {guess}. Hypothesis confirmed ({self.novel_hits}/2 credited)."
            reward = 0.3
        elif correct:
            obs = f"Correct! {token} -> {guess}. (No further credit for repeated or extra confirmations.)"
            reward = 0.0
        else:
            obs = f"Incorrect. {token} actually expands to: {actual}"
            reward = 0.0

        truncated = self.steps >= self.STEP_LIMIT
        self.done = truncated
        return obs, reward, False, truncated, {}
